import sys
from collections import deque, defaultdict
import errno

# Increase recursion depth for deep DFS
sys.setrecursionlimit(200000)

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return ""

    n = int(input_data[0])
    m = int(input_data[1])

    # Build adjacency list
    adj = defaultdict(list)
    for i in range(m):
        u = int(input_data[2 + 2*i])
        v = int(input_data[2 + 2*i + 1])
        adj[u].append(v)
        adj[v].append(u)

    # Find connected components using BFS/DFS
    visited = [False] * (n + 1)
    component_sizes = []

    for i in range(1, n + 1):
        if not visited[i]:
            size = 0
            queue = [i]
            visited[i] = True
            while queue:
                node = queue.pop()
                size += 1
                for neighbor in adj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        queue.append(neighbor)
            component_sizes.append(size)

    # Generate lucky numbers up to n
    lucky = []
    def gen_lucky(current, limit):
        if len(current) <= 10:  # max 10 digits for n <= 100000
            num = int(current)
            if num <= limit:
                lucky.append(num)
            if len(current) < 10:
                gen_lucky(current + "4", limit)
                gen_lucky(current + "7", limit)

    gen_lucky("", n)
    lucky.sort()

    # Check if any component already has lucky size
    if any(s in component_sizes for s in lucky):
        return "0\n"

    # For each lucky number, find minimum components needed to sum to it
    # Use dynamic programming: dp[s] = minimum number of components to get sum s
    dp = {}
    for size in component_sizes:
        new_dp = dp.copy()
        for s in list(new_dp.keys()):
            new_sum = s + size
            if new_sum not in dp and new_sum <= n:
                new_dp[new_sum] = min(new_dp.get(new_sum, float('inf')), dp.get(s, float('inf')) + 1)
        if not dp:
            dp = new_dp if new_dp else dp
        else:
            for s in list(dp.keys()):
                new_sum = s + size
                if new_sum <= n:
                    dp[new_sum] = min(dp.get(new_sum, float('inf')), dp.get(s, float('inf')) + 1)

    # Better DP approach for subsets
    dp = [-1] * (n + 1)
    dp[0] = 0

    for size in component_sizes:
        for s in range(n, size - 1, -1):
            if dp[s - size] != -1:
                dp[s] = min(dp[s], dp[s - size] + 1)

    result = float('inf')
    for L in lucky:
        if dp[L] != -1:
            result = min(result, dp[L])

    if result == float('inf'):
        return "-1\n"

    # Minimum roads = components - 1
    return f"{result - 1}\n"

