def solution(s):
    from collections import deque

    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Read edges
    edge_data = []
    for i in range(m):
        u, v, c = map(int, lines[i+1].split())
        edge_data.append((u, v, c))

    # Build adjacency list for BFS
    adj = [[] for _ in range(n + 1)]
    for idx, (u, v, c) in enumerate(edge_data):
        adj[u].append(v)
        adj[v].append(u)

    # BFS from source (vertex 1) to compute distances
    dist = [-1] * (n + 1)
    dist[1] = 0
    queue = deque([1])

    while queue:
        u = queue.popleft()
        for v in adj[u]:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    # Determine direction for each edge
    result = []
    for u, v, c in edge_data:
        # Flow goes from closer to source to farther from source
        if dist[u] < dist[v]:
            result.append('0')  # u -> v (ai -> bi)
        else:
            result.append('1')  # v -> u (bi -> ai)

    return '\n'.join(result)

def solution(s):
    lines = s.strip().split('\n')
    n, m = map(int, lines[0].split())
    grid = [list(lines[i+1]) for i in range(n)]

    changed = True
    max_iterations = n * m  # Safety limit
    iterations = 0

    while changed and iterations < max_iterations:
        changed = False
        iterations += 1

        visited = [[False] * m for _ in range(n)]
        for i in range(n):
            for j in range(m):
                if grid[i][j] == '.' and not visited[i][j]:
                    room = []
                    stack = [(i, j)]
                    visited[i][j] = True

                    while stack:
                        x, y = stack.pop()
                        room.append((x, y))

                        for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                            nx, ny = x + dx, y + dy
                            if 0 <= nx < n and 0 <= ny < m:
                                if grid[nx][ny] == '.' and not visited[nx][ny]:
                                    visited[nx][ny] = True
                                    stack.append((nx, ny))

                    min_r, max_r = min(r for r, c in room), max(r for r, c in room)
                    min_c, max_c = min(c for r, c in room), max(c for r, c in room)

                    for r in range(min_r, max_r + 1):
                        for c in range(min_c, max_c + 1):
                            if (r, c) not in room:
                                if grid[r][c] == '*':
                                    grid[r][c] = '.'
                                    changed = True

    grid_str = '\n'.join(''.join(row) for row in grid)
    return grid_str + '\n'

