import sys
import math

def solve_factorial_trailing_zeros(n):
    """Count trailing zeros in n! (factorial)"""
    if n < 5:
        return 0
    count = 0
    while n >= 5:
        n //= 5
        count += n
    return count

def solution(input_str):
    """
    Takes input string, parse the integer n,
    and output the number of trailing zeros in n!
    """
    n = int(input_str.strip())
    return str(solve_factorial_trailing_zeros(n))

