    offers = []
    for i in range(1, len(lines)):
        parts = lines[i].split()
        if len(parts) >= 2:
            l, r = int(parts[0]), int(parts[1])
            offers.append((l, r))

    results = []

    for x in range(1, n + 1):
        occupied = [False] * (n + 2)
        total_occupied = 0

        for l, r in offers:
            # Check duration requirement
            length = r - l + 1
            if length < x:
                continue

            # Check for overlap with already occupied days
            overlap = False
            for day in range(l, r + 1):
                if occupied[day]:
                    overlap = True
                    break

            if not overlap:
                # Mark all days as occupied
                for day in range(l, r + 1):
                    occupied[day] = True
                total_occupied += length

        results.append(str(total_occupied))

