from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '-1'

    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())

    edges = []
    adj = [[] for _ in range(n + 1)]

    for i in range(m):
        u, v, w = map(int, lines[2 + i].split())
        edges.append((u, v, w, i + 1))
        adj[u].append((v, i))
        adj[v].append((u, i))

    def can_reach(start, end):
        visited = [False] * (n + 1)
        queue = deque([start])
        visited[start] = True
        while queue:
            u = queue.popleft()
            if u == end:
                return True
            for v, idx in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)
        return False

    def remove_edges(edge_indices):
        for idx in edge_indices:
            u, v, w, eid = edges[idx - 1]
            adj[u].remove((v, idx - 1))
            adj[v].remove((u, idx - 1))
        return can_reach(s, t)

    # Restore edges for testing
    def restore_edges():
        for u, v, w, eid in edges:
            adj[u].append((v, eid - 1))
            adj[v].append((u, eid - 1))

    # Check if already disconnected
    if not can_reach(s, t):
        return '0\n0\n'

    best_result = None

    # Helper to remove the edges marked by indices
    def remove_and_restore(indices):
        for idx in indices:
            u, v, w, eid = edges[idx - 1]
            adj[u].remove((v, idx - 1))
            adj[v].remove((u, idx - 1))
        if not can_reach(s, t):
            return sum([edges[idx - 1][2] for idx in indices])
        # Restore
        for idx in indices:
            u, v, w, eid = edges[idx - 1]
            adj[u].append((v, eid - 1))
            adj[v].append((u, eid - 1))
        return None

    def restore_edges_all():
        for u, v, w, eid in edges:
            adj[u].append((v, eid - 1))
            adj[v].append((u, eid - 1))

    min_cost = float('inf')
    best_pair = None

    # For 0 roads: already handled above
    # For 1 road:
    for idx in range(m):
        u, v, w, eid = edges[idx]
        adj[u].remove((v, idx))
        adj[v].remove((u, idx))
        if not can_reach(s, t):
            if w < min_cost:
                min_cost = w
                best_pair = (idx + 1, idx + 1)  # Using same as represents count is 1
                # Actually we need to store which one road
                best_road = edges[idx]
            # Restore
            adj[u].append((v, idx))
            adj[v].append((u, idx))

    if min_cost < float('inf'):
        best_result = (min_cost, 1, (edges.index(best_road[1]), edges.index(best_road[0])))

    # For 2 roads:
    # Strategy: For each vertex v, find best edge from s to it (via 1 edge), and best edge from it to t

    # Get all vertices reachable from s with exactly 1 edge
    s_neighbors = [x[0] for x in adj[s]]
    s_edges = adj[s]  # list of (neighbor, edge_index)

    # Get all vertices that can reach t with exactly 1 edge
    t_neighbors = [x[0] for x in adj[t]]
    t_edges_in = [(x[0], i) for x in adj[t]]  # reverse direction

    # Try for each intermediate vertex
    for v in range(1, n + 1):
        if v == s or v == t:
            continue
            # If v is s or t, can't use as intermediate
            # continue

        # Find best edge from s to v
        best_from_s = None
        for (nv, eidx) in adj[s]:
            if nv == v:
                cost = edges[eidx][2]
                if best_from_s is None or cost < best_from_s[0]:
                    best_from_s = (cost, v, eidx)

        # Find best edge from v to t
        best_to_t = None
        for (nv, eidx) in adj[t]:
            if nv == v:
                cost = edges[eidx][2]
                if best_to_t is None or cost < best_to_t[0]:
                    best_to_t = (cost, v, eidx)

        if best_from_s and best_to_t:
            # These are different edges incident to s and t respectively
            cost = best_from_s[0] + best_to_t[0]
            if cost < min_cost:
                min_cost = cost
                best_result = (min_cost, 2, (edges.index(best_from_s[2]), edges.index(best_to_t[2])))

    # Another approach for 2 roads: try pairs of edges on same path
    # Find one path from s to t
    if best_result is None:
        path_edges = []
        def get_path():
            parent = {s: None}
            queue = deque([s])
            while queue:
                u = queue.popleft()
                if u == t:
                    path = []
                    curr = t
                    while curr is not None:
                        path.append(curr)
                        curr = parent[curr]
                    return path
                for (v, idx) in adj[u]:
                    if v not in parent:
                        parent[v] = (u, idx)
                        queue.append(v)
            return None

        path = get_path()
        if path:
            path = path[1:]  # remove s, these are vertices
            # Find edges between consecutive vertices in path
            for i in range(len(path) - 1):
                u, v = path[i], path[i+1]
                # Find edge index between u and v
                for (neighbor, idx) in adj[u]:
                    if neighbor == v:
                        path_edges.append(idx + 1)
                        break

            # Try removing consecutive edges
            for i in range(len(path_edges) - 1):
                idx1, idx2 = path_edges[i], path_edges[i+1]
                if idx1 != idx2:
                    cost = edges[idx1-1][2] + edges[idx2-1][2]
                    if cost < min_cost:
                        min_cost = cost
                        best_result = (min_cost, 2, (idx1, idx2))

        # Better: systematically try all pairs of edges that might disconnect
        # Try all edge pairs
        for i1 in range(m):
            idx1 = i1 + 1
            u1, v1, w1, eid1 = edges[i1]
            # Remove first edge
            adj[u1].remove((v1, eid1))
            adj[v1].remove((u1, eid1))

            for i2 in range(m):
                if i2 == i1:
                    continue
                idx2 = i2 + 1
                u2, v2, w2, eid2 = edges[i2]
                # Remove second edge
                adj[u2].remove((v2, eid2))
                adj[v2].remove((u2, eid2))

                if not can_reach(s, t):
                    cost = w1 + w2
                    if cost < min_cost and cost <= 2 ** 31:
                        min_cost = cost
                        best_result = (min_cost, 2, (idx1, idx2))

                # Restore second edge
                adj[u2].append((v2, eid2))
                adj[v2].append((u2, eid2))

            # Restore first edge
            adj[u1].append((v1, eid1))
            adj[v1].append((u1, eid1))

    if best_result and min_cost < float('inf'):
        return f"{min_cost}\n{best_result[1]}\n{best_result[2][0]} {best_result[2][1]}"

    # Special handling: if we found 1 edge removal, we need format
    for idx in range(m):
        u, v, w, eid = edges[idx]
        adj[u].remove((v, idx))
        adj[v].remove((u, idx))
        if not can_reach(s, t):
            best_result = (w, 1, idx + 1)
        adj[u].append((v, idx))
        adj[v].append((u, idx))

    if best_result and best_result[1] == 1:
        return f"{best_result[0]}\n{best_result[1]}\n{best_result[2]}"

    return '-1'

