        """Count total prime factors with multiplicity for a number x"""
        count = 0
        d = 2
        while d * d <= x:
            while x % d == 0:
                count += 1
                x //= d
            d += 1
        if x > 1:
            count += 1
        return count

    total = 0
    for num in a:
        total += count_prime_factors(num)

