# We need to find either:
# 1. A simple path with length >= n/k
# 2. k cycles with representatives, each having length >= 3 and not divisible by 3

import sys
from typing import List, Set, Dict, Tuple, Optional

class Solution:
    def __init__(self, n: int, edges: List[Tuple[int, int]]):
        self.n = n
        self.adj = [[] for _ in range(n + 1)]
        for u, v in edges:
            self.adj[u].append(v)
            self.adj[v].append(u)

    def get_cycles(self) -> List[List[int]]:
        """Find cycles with representatives. Each cycle must have length >= 3 and not divisible by 3."""
        cycles_with_rep = []
        used_vertex = [False] * (self.n + 1)

        for start in range(1, self.n + 1):
            if used_vertex[start]:
                continue

            # Try to build a cycle starting from 'start' as the representative
            # Using DFS to find cycles
            cycle = []
            stack = [(start, -1, start)]  # (current_node, parent, cycle_start_node)

            while stack:
                node, parent, start_node = stack.pop()

                if node == start and parent != -1 and len(cycle) > 0:
                    # Found a cycle back to start
                    cycle.append(node)
                    cycle_path = cycle[::-1]

                    # Check if length is >= 3 and not divisible by 3
                    if len(cycle_path) >= 3 and len(cycle_path) % 3 != 0:
                        cycles_with_rep.append(cycle_path)
                        # Mark vertices as used
                        for v in cycle_path:
                            used_vertex[v] = True
                        break

                if parent == -1:
                    continue

                for neighbor in self.adj[node]:
                    if neighbor != parent and neighbor not in [seen for _, _, _ in stack]:
                        visited = True
                        for _, _, sn in stack:
                            if neighbor == sn:
                                visited = False
                                break
                        if not visited:
                            cycle.append(node)
                            stack.append((neighbor, node, start_node))
                        if visited and cycle:
                            cycle.pop()

        return cycles_with_rep

    def find_cycles_with_deep_search(self, n: int, adj: List[List[int]]) -> List[List[int]]:
        """Find cycles using DFS for better cycle detection with representatives."""
        cycles = []
        visited = [False] * (n + 1)
        parent = [0] * (n + 1)
        rec_stack = [False] * (n + 1)
        path = [0] * (n + 1)
        path_len = 0

        def dfs(u: int) -> bool:
            nonlocal path_len
            path_len += 1
            path[path_len] = u
            visited[u] = True
            rec_stack[u] = True

            for v in adj[u]:
                if v == parent[u]:
                    continue
                if not visited[v]:
                    parent[v] = u
                    if dfs(v):
                        return True
                elif rec_stack[v]:
                    # Found back edge, we have a cycle
                    # Extract cycle
                    cycle = []
                    curr = v
                    cycle.append(v)
                    while curr != u:
                        curr = parent[curr]
                        cycle.append(curr)
                    cycle.append(u)
