                    cycle.sort()
                    cycle_str = " ".join(map(str, sorted(cycle)))

                    # Try to form longer or different cycles
                    return True

            rec_stack[u] = False
            path_len -= 1
            return False

        for i in range(1, n + 1):
            if not visited[i]:
                parent[i] = 0
                dfs(i)

        return cycles

    def find_long_path(self, n: int, k: int, adj: List[List[int]]) -> Optional[List[int]]:
        """Find a simple path with length >= n/k using DFS."""
        target_length = n // k

        visited = [False] * (n + 1)

        for start in range(1, n + 1):
            path = []
            if self.dfs_path(start, -1, path, visited, adj, n // k):
                return path

        return None

    def dfs_path(self, u: int, parent: int, path: List[int], visited: List[bool], adj: List[List[int]], target: int) -> bool:
        """DFS to find a path of required length."""
        path.append(u)
        visited[u] = True

        if len(path) >= target:
            return True

        for v in adj[u]:
            if v != parent and not visited[v]:
                if self.dfs_path(v, u, path, visited, adj, target):
