    lines = input_str.strip().split('\n')
    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for line in lines[1:m+1]:
        u, v = map(int, line.split())
        adj[u].append(v)
        adj[v].append(u)

    # Try to find path first
    target_len = n // k

    # DFS with cycle/path finding
    for start in range(1, n + 1):
        visited = [False] * (n + 1)

        def dfs_path(u, d):
            visited[u] = True
            path.append(u)

            if d >= target_len:
                return True

            # Sort neighbors by out-degree for better traversal
            neighbors = sorted([v for v in adj[u] if not visited[v]], 
                             key=lambda x: len(adj[x]) + (1 if (u, x) in [(x, u) for x in path] else 0), 
                             reverse=True)

            for v in neighbors:
                if dfs_path(v, d + 1):
                    return True

            visited[u] = False
            path.pop()
            return False

        path = []
        if dfs_path(start, 0):
            return "PATH\n" + str(len(path)) + "\n" + " ".join(map(str, path))

    # If no path, try to find k cycles
    visited = [False] * (n + 1)
    cycles = []
    reps = [False] * (n + 1)

    # Sort vertices by degree to try high-degree vertices first
    vertices = sorted(range(1, n + 1), key=lambda x: len(adj[x]), reverse=True)

    for start in vertices:
        if reps[start]:
            continue

        # Try to find cycle with 'start' as representative
        found = False
        visited_cycle = [False] * (n + 1)
        visited_cycle[start] = True
        path = [start]
        parent = {start: -1}

        q = [(start, start)]  # (current, visited_for_this_cycle)
        while q:
            curr, mask_node = q.pop()

            for neighbor in adj[curr]:
                if neighbor == parent.get(curr, None):
                    continue

                if neighbor == start and len(path) >= 3 and len(path) % 3 != 0:
                    cycles.append(path + [start])
                    reps[start] = True
                    found = True
                    break

                if neighbor != start and not visited_cycle[neighbor] and neighbor not in path:
                    visited_cycle[neighbor] = True
                    parent[neighbor] = curr
                    path.append(neighbor)
                    q.append((neighbor, neighbor))

            if found:
                visited_cycle = [False] * (n + 1)
                path = [start]
                break

        if found:
            continue

        # Alternative: DFS to find cycles
        vis = [False] * (n + 1)
        vis[start] = True

        def dfs(u, p):
            nonlocal found
            for v in adj[u]:
                if v != p and not vis[v]:
                    vis[v] = True
                    dfs(v, u)
                    vis[v] = False
                elif v != p and v in vis:
                    # Back edge found, potential cycle
                    # Extract cycle
                    idx = path.index(v) if v in path else 0
                    if len(path) - idx >= 3:
                        cycle = path[idx:] + [u, v]
                        if len(cycle) % 3 != 0:
                            cycles.append(path[idx:] + [u])
                            reps[start] = True
                            found = True

        dfs(start, -1)

        if found and len(cycles) >= k:
            output = ["CYCLES"]
            for c in cycles[:k]:
                output.append(str(len(c)))
                output.append(" ".join(map(str, c)))
            return "\n".join(output)

    return "-1"

def solution(input_str: str) -> str:
    return solution_impl(input_str)

