    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Compute subtree sizes
    subtree_size = [0] * (n + 1)
    subtree_size = compute_subtree_size(1, 0, adj, subtree_size)

    # Memoization for DP
    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(u, parent, sz):
        """
        Compute maximum product from subtree rooted at u,
        when the component containing u has size sz.
        """
        if sz == 1:
            return 1

        # Option 1: Accept u with its component of size sz, computing product
        result = sz

        for v in adj[u]:
            if v == parent:
                continue

            # Try cutting edge (u, v) - u's component finishes with size sz-1
            # and we gain something from v's subtree independently
            if sz - 1 >= 1:
                from_v = dp(v, u, 1)
                if from_v > 0:
                    result = max(result, result // sz * (sz - 1) * from_v)

        return result

    return dp(1, 0, n)

def compute_subtree_size(u, p, adj, subtree_size):
    sz = 1
    for v in adj[u]:
        if v != p:
            sz += compute_subtree_size(v, u, adj, subtree_size)
    subtree_size[u] = sz
    return sz

