    n = int(lines[0])
    arr = list(map(int, lines[1].split()))

    def is_gp(seq):
        length = len(seq)
        if length <= 2:
            return True

        # If first element is 0, all must be 0 for a valid GP
        if seq[0] == 0:
            return all(x == 0 for x in seq)

        arr0 = seq[0]
        arr1 = seq[1]

        for i in range(length - 1):
            # Check if arr[i+1]/arr[i] == arr[1]/arr[0] using cross multiplication
            # arr[i+1] * arr0 == arr[i] * arr1
            if arr[i] == 0:
                if arr[i+1] != 0:
                    return False
                continue

            if arr[i+1] * arr0 != arr[i] * arr1:
                return False

        return True

    # First check if already a GP
    if is_gp(arr):
        return "0"

    # Try removing each element and check if remaining is GP
    for i in range(n):
        new_arr = arr[:i] + arr[i+1:]
        if is_gp(new_arr):
            return "1"

    return "2"

import math

def solution(input_string):
    l, r = map(int, input_string.strip().split())

    # Handle edge case where range doesn't include valid primes
    if l > r:
        return "0\n"

    # Sieve to find primes up to sqrt(r)
    limit = int(math.isqrt(r)) + 1
    is_prime_small = [True] * limit
    is_prime_small[0] = is_prime_small[1] = False

    for i in range(2, int(math.isqrt(limit)) + 1):
        if is_prime_small[i]:
            for j in range(i * i, limit, i):
                is_prime_small[j] = False

    # Collect all primes up to sqrt(r)
    primes = [i for i, is_p in enumerate(is_prime_small) if is_p]

    # Sieve the range [l, r]
    seg_len = r - l + 1
    is_prime = [True] * seg_len

    # Handle 1 specially (not prime)
    if l == 1:
        is_prime[0] = False

    # Mark composite numbers in the range using small primes
    for p in primes:
        # Find first multiple of p >= l
        start = max(p * p, (l + p - 1) // p * p)

        # Calculate index in segment array
        start_idx = (start - l + p - 1) // p if start >= l else -1

        # Mark all multiples of p in the segment
        if start_idx >= 0:
            for j in range(start_idx, seg_len):
                if (l + j) % p == 0:
                    is_prime[j] = False

    # Count primes that are 2 or ≡ 1 (mod 4)
    count = 0
    for i in range(seg_len):
        num = l + i
        if is_prime[i] and (num == 2 or num % 4 == 1):
            count += 1

    return f"{count}\n"

from collections import deque

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    numbers = list(map(int, lines[1].split()))

    def f(x):
        """Reduce x by repeatedly dividing by k until not divisible"""
        while x % k == 0:
            x //= k
        return x

    # Initial state as sorted tuple for memoization
    initial_state = tuple(sorted(numbers))

    # Check if already single number equal to 1
    if len(initial_state) == 1 and initial_state[0] == 1:
        return "YES"

    # BFS state: (current_tuple_of_numbers, list_of_operations)
    queue = deque([(initial_state, [])])
    visited = {initial_state}
    target_reached = None

    while queue:
        state, ops = queue.popleft()

        # Check if this is our target state (single number = 1)
        if len(state) == 1 and state[0] == 1:
            target_reached = ops
            break

        # If only one number left and it's not 1, can't reach target
        if len(state) == 1:
            continue

        # Try all pairs to combine
        for i in range(len(state)):
            for j in range(i + 1, len(state)):
                x, y = state[i], state[j]
                z = x + y
                new_val = f(z)

                # Build new state without x and y, adding new_val
                new_nums = []
                for idx, val in enumerate(state):
                    if idx != i and idx != j:
                        new_nums.append(val)
                new_nums.append(new_val)
                new_state = tuple(sorted(new_nums))

                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, ops + [(x, y)]))

    if target_reached is not None:
        result = "YES"
        for x, y in target_reached:
            result += f"\n{x} {y}"
        return result
    else:
        return "NO"

