    # City i prefers city j with lower cost
    preferences = []
    for i in range(n):
        city_costs = []
        for j in range(n):
            if i != j:
                city_costs.append((costs[i][j], j))  # (cost, city)
        # Sort by cost ascending
        city_costs.sort(key=lambda x: x[0])
        # Store just the city indices
        preferences.append([c[1] for c in city_costs])

    # Use a simplified stable matching attempt
    # For this problem, we try greedy matching and then validate stability
    # If N is even, start with simple greedy pairing by lowest costs

    # Try different starting pairings and check for blocking pairs
    def is_stable(matching):
        """Check if matching is stable - no blocking pairs exist"""
        partner = [None] * n  # partner[i] = city paired with i

        for i, j in matching.items():
