                # Check if p would prefer i over their current partner
                p_partner = partner[p]
                if p_partner is None or p_partner == i:
                    continue

                # Check if p prefers i over p_partner
                if p in preferences[i]:  # i is in p's preferences
                    if preferences[i].index(p) < preferences[i].index(p_partner):
                        # p prefers i, now check if i prefers p
                        if preferences[i].index(p) < preferences[i].index(current_partner):
                            return False  # Blocking pair (i, p) exists

        return True

    def get_pref_index(city, pref_list):
        """Get preference index of city (lower = more preferred)"""
        try:
            return pref_list.index(city)
        except:
            return len(pref_list)

    # Try all possible stable matchings using backtracking with early stopping
    # Since N <= 1000, we need efficient approach

    # Use algorithm: try to build matching greedily, then verify stability
    # If no stable matching found, return -1

    # Greedy approach: sort all edges by cost and try to form pairs
    import itertools

