        for j in range(i + 1, n):
            # Take minimum of both directions
            cost1 = costs[i][j]
            cost2 = costs[j][i]
            all_edges.append((min(cost1, cost2), i, j))

    all_edges.sort()

    # Listenroof's algorithm for stable roommates
    result = [-1] * n
    matched = [False] * n

    def backtrack(idx):
        if idx == len(all_edges):
            # All edges considered, check if we have complete matching
            for i in range(n):
                if not matched[i]:
                    return False
            return True

        cost, i, j = all_edges[idx]

