            matched[j] = True
            result[i] = j
            result[j] = i

            if backtrack(idx + 1):
                return True

            # Backtrack
            matched[i] = False
            matched[j] = False
            result[i] = -1
            result[j] = -1

        # Try not including this edge
        if backtrack(idx + 1):
            return True

        return False

    # For large N, this approach may be too slow. 
