        # For n = 4k + r, after k full scatterings we have a pattern

        k = n // 4

        # Threshold distance where pattern begins
        threshold = k + 1

        if r == 0:
            # At origin - depends on remainder
            return 0 if r % 4 == 0 else 1

        if r > threshold or r % 4 == 0 and r != 0:
            # Beyond reach or special case
            return 0

        # Calculate binomial coefficient contribution
        # The pattern involves combinatorics at each distance
        available = k

        if r <= 1:
            return r
        elif r == 2:
            if available >= 1:
                return 1
            return 0
        elif r <= available + 1:
            # General case: binomial contribution
            return 1 if (r - 1) % 4 != 0 else 0
        else:
            return 0

