def get_sphere_from_boundary(boundary):
    """Get sphere defined by boundary points"""
    if len(boundary) == 0:
        return [0.0, 0.0, 0.0], 0.0
    elif len(boundary) == 1:
        return sphere_from_1(boundary[0])
    elif len(boundary) == 2:
