                    best = c, r
                    best_r = r
        return best[0], best[1] if best else [0,0,0], best_r if best else 0

def welzl(points, boundary):
    """Welzl's algorithm for minimum enclosing sphere"""
    if len(points) == 0:
        c, r = get_sphere_from_boundary(boundary)
        return c, r

    # Pick a random point and process
    idx = random.randint(0, len(points)-1)
