def solution(input_str):
    lines = input_str.strip().split('\n')
    n, q = map(int, lines[0].split())

    # Initialize permutation (1-indexed for convenience)
    a = list(range(n + 1))  # a[0] unused

    def count_inversions():
        cnt = 0
        for i in range(1, n + 1):
            for j in range(i + 1, n + 1):
                if a[i] > a[j]:
                    cnt += 1
        return cnt

    result = []

    for i in range(1, q + 1):
        l, r = map(int, lines[i].split())
        if l == r:
            result.append(str(count_inversions()))
            continue

        # Swap elements
        a[l], a[r] = a[r], a[l]
        result.append(str(count_inversions()))

    return '\n'.join(result)

