    result = []

    idx = 1
    for _ in range(t):
        if idx >= len(lines):
            break
        n, m = map(int, lines[idx].split())
        idx += 1

        matrix = []
        for i in range(n):
            matrix.append(list(lines[idx + i]))
        idx += n

        count = 0
        N = n
        M = m

        # Build set of 1s for quick lookup
        ones = set()
        for i in range(N):
            for j in range(M):
                if matrix[i][j] == '1':
                    ones.add((i, j))

        # Check axis-aligned squares
        for r in range(N):
            for c in range(M):
                for k in range(2, min(N - r, M - c + 1)):
                    r1, c1 = r, c
                    r2, c2 = r + k - 1, c + k - 1

                    # Check border is all 1s
                    border_ok = True

                    for j in range(c1, c2 + 1):
                        if (r1, j) not in ones:
                            border_ok = False
                            break
                    if not border_ok:
                        continue

                    for j in range(c1, c2 + 1):
                        if (r2, j) not in ones:
                            border_ok = False
                            break
                    if not border_ok:
                        continue

                    for i in range(1, k - 1):
                        if (r1 + i, c1) not in ones or (r1 + i, c2) not in ones:
                            border_ok = False
                            break
                    if not border_ok:
                        continue

                    # Check no foreign 1s touching the border (by side)
                    top_clear = True
                    if r1 - 1 >= 0:
                        for j in range(c1, c2 + 1):
                            if (r1 - 1, j) in ones:
                                top_clear = False
                                break
                    if not top_clear:
                        continue

                    bottom_clear = True
                    if r2 + 1 < N:
                        for j in range(c1, c2 + 1):
                            if (r2 + 1, j) in ones:
                                bottom_clear = False
                                break
                    if not bottom_clear:
                        continue

                    left_clear = True
                    if c1 - 1 >= 0:
                        for i in range(r1, r2 + 1):
                            if (i, c1 - 1) in ones:
                                left_clear = False
                                break
                    if not left_clear:
                        continue

                    right_clear = True
                    if c2 + 1 < M:
                        for i in range(r1, r2 + 1):
                            if (i, c2 + 1) in ones:
                                right_clear = False
                                break
                    if not right_clear:
                        continue

                    count += 1

        # Check diagonal squares (diamonds)
        for r in range(N):
            for c in range(M):
                # Check possible radius values
                for rr in range(1, min(N - r, M - c)):
                    # Diamond of radius rr, center at (r, c)
                    # Border: |i - r| + |j - c| == rr

                    # Collect border cells, check they're all 1s, and no foreign 1s touch
                    border_ok = True
                    rr_ok = True

                    # Check border cells exist and are '1'
                    for i_offset in range(-rr, rr + 1):
                        j_offset = abs(i_offset)  # |i - r| + |j - c| = rr => |j - c| = rr - |i - r|
                        for j_buf in [j_offset, -j_offset]:
                            j_border = c + j_buf
                            if not (0 <= j_border < M):
                                border_ok = False
                                rr_ok = False
                                break
                            if (r + i_offset, j_border) not in ones:
                                border_ok = False
                                rr_ok = False
                                break
                        if not border_ok:
                            rr_ok = False
                            break
                        if not rr_ok:
                            break
                    if not rr_ok or not border_ok:
                        continue

                    # Check no foreign 1s touching the border (by side)
                    # Cells adjacent to border (Manhattan distance rr+1 from center, or distance rr but not on border)
                    for i_add in range(-rr - 1, rr + 2):
                        for j_add in range(-abs(i_add) - 1, abs(i_add) + 2):
                            ni, nj = r + i_add, c + j_add
                            if not (0 <= ni < N and 0 <= nj < M):
                                continue
                            # Check if touching border
                            if (abs(i_add - rr) + abs(j_add - rr) == 1) or \
                               (i_add == i_offset and j_add == j_buf + 1) or \
                               (ni, nj) in once_where_distance_rplus1_at_center(r, c, rr + 1, N, M):
                                pass
                            if (ni, nj) in ones:
                                border_ok = False
                                rr_ok = False
                                break
                        if not rr_ok:
                            break
                    if not rr_ok:
                        continue

                    count += 1

        result.append(str(count))

    return '\n'.join(result)

import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    n, d = map(int, lines[0].split())
    circles = []
    for i in range(1, n + 1):
        if lines[i].strip():
            x, y, r = map(int, lines[i].split())
            circles.append((x, y, r))

    if not circles:
        return "0\n"

    def get_angle_interval(x, y, r, k):
        dist_sq = x*x + y*y
        dist = math.sqrt(dist_sq)

        # Handle centered at origin
        if dist == 0:
            if k * d <= r:
                return (0, 2 * math.pi)
            else:
                return None

        t = k * d

        # Check if valid distance range first
        lower = abs(dist - r)
        upper = dist + r
        if not (lower <= t <= upper):
            return None

        numerator = t*t + dist*dist - r*r
        denominator = 2 * t * dist

        if denominator <= 0:
            return None

        cot = numerator / denominator
        cot = max(-1.0, min(1.0, cot))

        if cot <= -1.0:
            return (0, 2 * math.pi)
        elif cot >= 1.0:
            return None
        else:
            delta = math.acos(cot)
            phi = math.atan2(y, x)

            start = phi - delta
            end = phi + delta

            # Normalize to [0, 2π)
            start = start % (2 * math.pi)
            end = end % (2 * math.pi)

            # Split wrapping interval
            if start > end:
                return ((start, 2 * math.pi), (0, end])
            else:
                return ((start, end], None)

    intervals = []

    # Calculate reasonable upper bound for k
    max_coord = 10000
    max_dist_from_origin = math.sqrt(max_coord*max_coord + max_coord*max_coord) + 50
    max_k = int(max_dist_from_origin / d) + 10

    # Also limit by circle distances
    max_circle_dist = 0
    for x, y, r in circles:
        max_circle_dist = max(max_circle_dist, math.sqrt(x*x + y*y) + r)
    max_k = min(max_k, int(max_circle_dist / d) + 5)

    for k in range(1, max_k + 1):
        for x, y, r in circles:
            interval = get_angle_interval(x, y, r, k)
            if interval:
                intervals.append(interval)

    if not intervals:
        return "0\n"

    # Split wrapping intervals to linear form on [0, 2π)
    linear_intervals = []
    for start, end_end in intervals:
        if end_end is None:
            linear_intervals.append((start, 2 * math.pi))
            linear_intervals.append((0, end_end))
        else:
            linear_intervals.append((start, end_end))

    # Sweep line algorithm
    events = []
    for l, r in linear_intervals:
        events.append((l, 1))
        events.append((r, -1))

    events.sort()

    max_hits = 0
    current = 0
    for _, change in events:
        current += change
        max_hits = max(max_hits, current)

    return f"{max_hits}\n"

def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return "0\n"

    N, M, K = map(int, lines[0].split())

    # Parse transformers
    transformers = []
    for i in range(1, K + 1):
        parts = lines[i].split()
        if len(parts) >= 5:
            x, y, d, t, e = int(parts[0]), int(parts[1]), int(parts[2]), int(parts[3]), int(parts[4])
            transformers.append((x, y, d, t, e))

    # Build positions map: pos_map[(r, c)][time] = list of (index, energy)
    pos_map = {}

    max_time = N + M - 1

    for i in range(K):
        x, y, d, t_start, e = transformers[i]

        for step in range(4):
            # Transformer cycle positions based on step
            if step == 0:
                r, c = x, y
            elif step == 1:
                r, c = x + d, y - d
            elif step == 2:
                r, c = x + d, y
            elif step == 3:
                r, c = x, y + d

            t = t_start + step

            # Check bounds and time
            if r < 0 or r >= N or c < 0 or c >= M:
                continue
            if t > max_time:
                continue

            if (r, c) not in pos_map:
                pos_map[(r, c)] = {}

            if t not in pos_map[(r, c)]:
                pos_map[(r, c)][t] = []

            pos_map[(r, c)][t].append((i, e))

    # DP: dp[r][c] = minimum energy to reach (r,c)
    INF = float('inf')
    dp = [[INF] * M for _ in range(N)]

    # Starting position
    cost = 0
    if (0, 0) in pos_map and (0 + 0) in pos_map[(0, 0)]:
        cost = sum(e for _, e in pos_map[(0, 0)][0])
    dp[0][0] = cost

    # Fill DP table
    for r in range(N):
        for c in range(M):
            if r > 0:
                dp[r][c] = min(dp[r][c], dp[r-1][c])
            if c > 0:
                dp[r][c] = min(dp[r][c], dp[r][c-1])

            # Add cost of transformers at this position at time r+c
            if (r, c) in pos_map and (r + c) in pos_map[(r, c)]:
                dp[r][c] += sum(e for _, e in pos_map[(r, c)][r + c])

    return str(dp[N-1][M-1]) + "\n"

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        matrix.append(list(map(int, lines[i].split())))

    def get_factors(num):
        """Returns (count of 2s, count of 5s) for the prime factors"""
        if num == 0:
            return (0, 0)
        c2 = 0
        c5 = 0
        temp = num
        while temp % 2 == 0:
            c2 += 1
            temp //= 2
        while temp % 5 == 0:
            c5 += 1
            temp //= 5
        return (c2, c5)

    # dp[i][j] = list of (count2, count5, path) - keep Pareto optimal
    dp = [[[] for _ in range(n)] for _ in range(n)]

    # Starting cell
    start_factors = get_factors(matrix[0][0])
    dp[0][0] = [(start_factors[0], start_factors[1], "")]

    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            curr_factors = get_factors(matrix[i][j])
            options = []

            # From top
            if i > 0:
                for c2, c5, path in dp[i-1][j]:
                    options.append((c2 + curr_factors[0], c5 + curr_factors[1], path + 'D'))

            # From left
            if j > 0:
                for c2, c5, path in dp[i][j-1]:
                    options.append((c2 + curr_factors[0], c5 + curr_factors[1], path + 'R'))

            # Keep only Pareto optimal entries
            # A point dominates another if it's better or equal in both dimensions
            result = []
            for opt in options:
                # Check if dominated by existing
                dominated = False
                for pr2, pr5, _ in result:
                    if pr2 <= opt[0] and pr5 <= opt[1] and (pr2 < opt[0] or pr5 < opt[1]):
                        dominated = True
                        break
                if not dominated:
                    # Remove entries dominated by this new option
                    new_result = []
                    for pr2, pr5, path in result:
                        if not (pr2 >= opt[0] and pr5 >= opt[1] and (pr2 > opt[0] or pr5 > opt[1])):
                            new_result.append((pr2, pr5, path))
                    result = new_result
                    result.append(opt)

            dp[i][j] = result

    # Find minimum trailing zeros
    best = None
    for c2, c5, path in dp[n-1][n-1]:
        zeros = min(c2, c5)
        if best is None:
            best = (zeros, path)
        else:
            curr_zeros, curr_path = best
            if zeros < curr_zeros:
                best = (zeros, path)
            elif zeros == curr_zeros:
                if path < curr_path:
                    best = (zeros, path)

    return f"{best[0]}\n{best[1]}"

class SegmentTree:
    def __init__(self, data):
        self.n = len(data)
        self.tree = [float('inf')] * (4 * self.n)
        self.lazy = [0] * (4 * self.n)
        self.build(data, 1, 0, self.n - 1)

    def build(self, data, node, start, end):
        if start == end:
            self.tree[node] = data[start]
        else:
            mid = (start + end) // 2
            self.build(data, 2 * node, start, mid)
            self.build(data, 2 * node + 1, mid + 1, end)
            self.tree[node] = min(self.tree[2 * node], self.tree[2 * node + 1])

    def push(self, node):
        if self.lazy[node] != 0:
            self.tree[2 * node] += self.lazy[node]
            self.lazy[2 * node] += self.lazy[node]
            self.tree[2 * node + 1] += self.lazy[node]
            self.lazy[2 * node + 1] += self.lazy[node]
            self.lazy[node] = 0

    def update(self, node, start, end, l, r, val):
        if r < start or end < l:
            return
        if l <= start and end <= r:
            self.tree[node] += val
            self.lazy[node] += val
            return
        self.push(node)
        mid = (start + end) // 2
        self.update(2 * node, start, mid, l, r, val)
        self.update(2 * node + 1, mid + 1, end, l, r, val)
        self.tree[node] = min(self.tree[2 * node], self.tree[2 * node + 1])

    def query_min(self, node, start, end, l, r):
        if r < start or end < l:
            return float('inf')
        if l <= start and end <= r:
            return self.tree[node]
        self.push(node)
        mid = (start + end) // 2
        left = self.query_min(2 * node, start, mid, l, r)
        right = self.query_min(2 * node + 1, mid + 1, end, l, r)
        return min(left, right)

