def solution(input_str):
    lines = input_str.strip().split('\n')
    data = lines[0].split()
    n, a, b = int(data[0]), int(data[1]), int(data[2])
    p = list(map(int, lines[1].split()))

    # Map each number to its index
    number_to_index = {p[i]: i for i in range(n)}

    # Union-Find
    parent = list(range(n))

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px

    # constraint[i] tracks whether each element is forced to a specific set
    # 0 = must be in A, 1 = must be in B, -1 = not forced
    constraint = [-1] * n

    for i in range(n):
        # Check 'a' constraint: if a - p[i] doesn't exist, p[i] cannot be in A
        target_a = a - p[i]
        if target_a not in number_to_index:
            constraint[i] = 1  # Must be in B
        else:
            j = number_to_index[target_a]
            union(i, j)

        # Check 'b' constraint: if b - p[i] doesn't exist, p[i] cannot be in B
        target_b = b - p[i]
        if target_b not in number_to_index:
            constraint[i] = 0  # Must be in A
        else:
            j = number_to_index[target_b]
            union(i, j)

    # Group constraints by component
    # forced[root] = 0 means component must be in A
    # forced[root] = 1 means component must be in B
    forced = {}

    possible = True

    # First pass: collect forced assignments
    for i in range(n):
        root = find(i)
        if constraint[i] == -1:
            continue
        if root not in forced:
            forced[root] = []
        forced[root].append(constraint[i])

    # Second pass: check for contradictions
    for root, constraints in forced.items():
        if 0 in constraints and 1 in constraints:
            possible = False
            break

    if not possible:
        return "NO\n"

    # Build final assignment
    # If a component has restrictions, all elements in it get same constraint
    # Otherwise default to A (0)
    result = []
    for i in range(n):
        root = find(i)
        if root in forced:
            val = forced[root][0]
        else:
            val = 0
        result.append(str(val))

    return "YES\n" + " ".join(result) + "\n"


