    MOD = 10**9 + 7

    if k == 1:
        return str(n % MOD)

    @lru_cache(maxsize=None)
    def count_paths(pos, step, visited_mask):
        if step == k:
            return 1

        res = 0
        # Try all possible next positions
        for nxt in range(max(1, pos - m), min(n, pos + m) + 1):
            if not (visited_mask >> (nxt - 1)) & 1:
                res = (res + count_paths(nxt, step + 1, visited_mask | (1 << (nxt - 1)))) % MOD
        return res

    total_sum = 0
    for start in range(1, n + 1):
        total_sum = (total_sum + count_paths(start, 1, 1 << (start - 1))) % MOD

    return str(total_sum)


