        # 0 if already divisible, b if changeable, inf otherwise
        cost = []
        for x in arr:
            rem = x % d
            if rem == 0:
                cost.append(0)
            elif rem == 1 or (d - rem) == 1:
                cost.append(b)
            else:
                cost.append(float('inf'))

        # Precompute prefix valid sums
        prefix_sum = [0] * (n + 1)
        for i in range(n):
            if cost[i] > b:
                prefix_sum[i+1] = float('inf')
                continue
            prefix_sum[i+1] = prefix_sum[i] + cost[i]

        # Initialize answer with "no removal" case
        if prefix_sum[n] <= n * b:
