        # Try removing [i, j) where we keep prefix [0, i) and suffix [j, n)
        for j in range(n):
            # Skip invalid positions at start of suffix
            if cost[j] > b:
                continue

            # Find max valid starting position for prefix
            for i in range(j):
                if cost[i] > b:
                    break
                # Elements [i+1, j-1] are removed, elements [0, i] and [j, n-1] kept
                if i == 0:
                    prefix_cost = 0
                else:
