def simulate_move(x, y, direction, n, m, swapLR, swapUD):
    """Simulate a move and return new position. Out of bounds positions stay the same."""
    if not (1 <= x <= n and 1 <= y <= m):
        return x, y

    if not (1 <= x <= n and 1 <= y <= m):
        return x, y

    nx, ny = x, y

    if direction == 'U':
        if swapUD:
            nx += 1
        else:
            nx -= 1
    elif direction == 'D':
        if swapUD:
            nx -= 1
        else:
            nx += 1
    elif direction == 'L':
        if swapLR:
            ny += 1
        else:
            ny -= 1
    elif direction == 'R':
        if swapLR:
            ny -= 1
        else:
            ny += 1

    # Check bounds again after direction adjustment
    if not (1 <= nx <= n and 1 <= ny <= m):
        return x, y

    return nx, ny


